ddl:
CREATE TABLE `channel_name` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY ,
  `name` varchar(255) DEFAULT NULL
);

CREATE TABLE `channel_type` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY ,
  `name` varchar(255) DEFAULT NULL
);

CREATE TABLE `ocean_region` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY ,
  `name` varchar(255) DEFAULT NULL
);

CREATE TABLE `signalling_unit` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY ,
  `time` timestamp NULL DEFAULT NULL,
  `channel_name_id` int(10) unsigned DEFAULT NULL,
  `ocean_region_id` int(10) unsigned DEFAULT NULL,
  `ges_id` int(10) unsigned DEFAULT NULL,
  `channel_unit_id` int(10) unsigned DEFAULT NULL,
  `channel_type_id` int(10) unsigned DEFAULT NULL,
  `su_type_id` int(10) unsigned DEFAULT NULL,
  `burst_frequency_offset` varchar(255) DEFAULT NULL,
  `burst_timing_offset` varchar(255) DEFAULT NULL,
  `stage_id` int(10) unsigned DEFAULT NULL,
  FOREIGN KEY (`channel_name_id`) REFERENCES `channel_name` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  FOREIGN KEY (`ocean_region_id`) REFERENCES `ocean_region` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  FOREIGN KEY (`channel_type_id`) REFERENCES `channel_type` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  FOREIGN KEY (`su_type_id`) REFERENCES `su_type` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  FOREIGN KEY (`stage_id`) REFERENCES `stage` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
);

CREATE TABLE `stage` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY ,
  `name` varchar(255) DEFAULT NULL
);

CREATE TABLE `su_type` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY ,
  `name` varchar(255) DEFAULT NULL
) ;
